// mock-socket-io.js — 影子系统本地 Socket.IO 客户端仿生程序
window.io = function(url, options) {
  console.log("Mock Socket.IO Initialized for connection:", url, options);
  
  const eventListeners = {};
  
  const socket = {
    connected: true,
    
    on: function(event, callback) {
      if (!eventListeners[event]) {
        eventListeners[event] = [];
      }
      eventListeners[event].push(callback);
      return this;
    },
    
    emit: function(event, data) {
      console.log(`Mock Socket.IO Emit [${event}]:`, data);
      return this;
    },
    
    disconnect: function() {
      this.connected = false;
      console.log("Mock Socket.IO Disconnected.");
      return this;
    }
  };

  // Periodically fetch live mock data from the backend to simulate a real SocketIO 'update' event
  function triggerMockUpdates() {
    if (!socket.connected) return;
    
    fetch('/api/data')
      .then(res => res.json())
      .then(data => {
        if (eventListeners['update']) {
          eventListeners['update'].forEach(cb => {
            try {
              cb(data);
            } catch (err) {
              console.error("Error in SocketIO 'update' listener:", err);
            }
          });
        }
      })
      .catch(err => console.error("Mock SocketIO data tick fetch failure:", err));
  }

  // Trigger initial tick fast, then every 3 seconds
  setTimeout(triggerMockUpdates, 1000);
  setInterval(triggerMockUpdates, 3000);

  return socket;
};
